     1	package com.loja.order.service;
     2	
     3	import com.loja.order.domain.*;
     4	import com.loja.order.model.OrderSummary;
     5	import com.loja.order.util.RoundingUtil;
     6	import org.springframework.stereotype.Service;
     7	import java.math.BigDecimal;
     8	import java.util.List;
     9	
    10	@Service
    11	public class PricingService {
    12	
    13	  public OrderSummary calculateSummary(
    14	    List<SummaryItem> items,
    15	    String couponCode,
    16	    ShippingMethod shippingMethod,
    17	    BigDecimal shippingCost,
    18	    int deliveryDays,
    19	    Region region,
    20	    PaymentMethod paymentMethod,
    21	    int installments,
    22	    ClubTier clubTier,
    23	    boolean isFirstPurchase
    24	  ) {
    25	    BigDecimal productsSubtotal = calculateProductsSubtotal(items);
    26	
    27	    BigDecimal couponDiscount = calculateCouponDiscount(
    28	      couponCode, productsSubtotal, items, isFirstPurchase, shippingMethod, shippingCost
    29	    );
    30	
    31	    BigDecimal finalShippingCost = calculateShippingCost(
    32	      shippingCost, clubTier, shippingMethod, couponCode
    33	    );
    34	
    35	    BigDecimal insurance = calculateInsurance(productsSubtotal, region);
    36	
    37	    BigDecimal subtotalAfterDiscount = productsSubtotal.subtract(couponDiscount)
    38	      .add(finalShippingCost).add(insurance);
    39	
    40	    BigDecimal paymentAdjustment = calculatePaymentAdjustment(
    41	      subtotalAfterDiscount, paymentMethod, installments, couponCode
    42	    );
    43	
    44	    BigDecimal finalTotal = subtotalAfterDiscount.add(paymentAdjustment);
    45	
    46	    BigDecimal installmentAmount = calculateInstallmentAmount(
    47	      finalTotal, paymentMethod, installments
    48	    );
    49	
    50	    BigDecimal nextPurchaseCredit = calculateCredit(
    51	      productsSubtotal, clubTier
    52	    );
    53	
    54	    boolean gift = shouldGiveGift(productsSubtotal, clubTier);
    55	
    56	    return new OrderSummary(
    57	      RoundingUtil.roundHalfEven(productsSubtotal),
    58	      RoundingUtil.roundHalfEven(couponDiscount),
    59	      RoundingUtil.roundHalfEven(finalShippingCost),
    60	      deliveryDays,
    61	      RoundingUtil.roundHalfEven(insurance),
    62	      RoundingUtil.roundHalfEven(paymentAdjustment),
    63	      RoundingUtil.roundHalfEven(finalTotal),
    64	      installments,
    65	      RoundingUtil.roundHalfEven(installmentAmount),
    66	      RoundingUtil.roundHalfEven(nextPurchaseCredit),
    67	      gift
    68	    );
    69	  }
    70	
    71	  private BigDecimal calculateProductsSubtotal(List<SummaryItem> items) {
    72	    return items.stream()
    73	      .map(item -> item.price().multiply(new BigDecimal(item.quantity())))
    74	      .reduce(BigDecimal.ZERO, BigDecimal::add);
    75	  }
    76	
    77	  private BigDecimal calculateCouponDiscount(
    78	    String couponCode,
    79	    BigDecimal productsSubtotal,
    80	    List<SummaryItem> items,
    81	    boolean isFirstPurchase,
    82	    ShippingMethod shippingMethod,
    83	    BigDecimal shippingCost
    84	  ) {
    85	    if (couponCode == null || couponCode.isEmpty()) {
    86	      return BigDecimal.ZERO;
    87	    }
    88	
    89	    Coupon coupon = Coupon.fromCode(couponCode).orElse(null);
    90	    if (coupon == null) {
    91	      return BigDecimal.ZERO;
    92	    }
    93	
    94	    List<Coupon.OrderItem> couponItems = items.stream()
    95	      .map(item -> new Coupon.OrderItem(item.sku(), item.quantity(), item.price()))
    96	      .toList();
    97	
    98	    Coupon.OrderContext ctx = new Coupon.OrderContext(
    99	      couponItems,
   100	      isFirstPurchase,
   101	      shippingMethod,
   102	      shippingCost
   103	    );
   104	
   105	    BigDecimal discount = coupon.calculateDiscount(productsSubtotal, ctx)
   106	      .orElse(BigDecimal.ZERO);
   107	
   108	    BigDecimal maxDiscount = productsSubtotal.multiply(new BigDecimal("0.30"));
   109	
   110	    if (discount.compareTo(maxDiscount) > 0) {
   111	      discount = maxDiscount;
   112	    }
   113	
   114	    return RoundingUtil.roundHalfEven(discount);
   115	  }
   116	
   117	  private BigDecimal calculateShippingCost(
   118	    BigDecimal shippingCost,
   119	    ClubTier clubTier,
   120	    ShippingMethod shippingMethod,
   121	    String couponCode
   122	  ) {
   123	    if (shippingMethod == ShippingMethod.STORE_PICKUP) {
   124	      return BigDecimal.ZERO;
   125	    }
   126	
   127	    if (clubTier.isFreeShippingAllowed() && shippingMethod != ShippingMethod.COURIER) {
   128	      return BigDecimal.ZERO;
   129	    }
   130	
   131	    if ("FREESHIPPING".equals(couponCode) && shippingMethod != ShippingMethod.STORE_PICKUP) {
   132	      return BigDecimal.ZERO;
   133	    }
   134	
   135	    return shippingCost;
   136	  }
   137	
   138	  private BigDecimal calculateInsurance(BigDecimal productsSubtotal, Region region) {
   139	    BigDecimal insurance = productsSubtotal.multiply(
   140	      new BigDecimal(region.getInsuranceRate())
   141	    );
   142	
   143	    if (region.getInsuranceLimit() != null) {
   144	      BigDecimal limit = region.getInsuranceLimit();
   145	      if (insurance.compareTo(limit) > 0) {
   146	        insurance = limit;
   147	      }
   148	    }
   149	
   150	    return RoundingUtil.roundHalfEven(insurance);
   151	  }
   152	
   153	  private BigDecimal calculatePaymentAdjustment(
   154	    BigDecimal subtotal,
   155	    PaymentMethod paymentMethod,
   156	    int installments,
   157	    String couponCode
   158	  ) {
   159	    return switch (paymentMethod) {
   160	      case PIX -> {
   161	        if (couponCode != null && !couponCode.isEmpty()) {
   162	          yield BigDecimal.ZERO;
   163	        }
   164	        yield subtotal.multiply(new BigDecimal("-0.05"));
   165	      }
   166	      case CREDIT_CARD -> {
   167	        if (installments <= 3) {
   168	          yield BigDecimal.ZERO;
   169	        }
   170	        BigDecimal monthlyRate = new BigDecimal("0.0199");
   171	        BigDecimal numerator = subtotal.multiply(monthlyRate);
   172	        BigDecimal denominator = new BigDecimal("1").subtract(
   173	          new BigDecimal("1").add(monthlyRate).pow(-(installments),
   174	            new java.math.MathContext(10))
   175	        );
   176	        BigDecimal installmentValue = numerator.divide(denominator, 10, java.math.RoundingMode.HALF_EVEN);
   177	        BigDecimal totalWithInterest = installmentValue.multiply(new BigDecimal(installments));
   178	        yield totalWithInterest.subtract(subtotal);
   179	      }
   180	      case BANK_SLIP -> new BigDecimal("3.49");
   181	    };
   182	  }
   183	
   184	  private BigDecimal calculateInstallmentAmount(
   185	    BigDecimal finalTotal,
   186	    PaymentMethod paymentMethod,
   187	    int installments
   188	  ) {
   189	    if (installments == 1) {
   190	      return finalTotal;
   191	    }
   192	
   193	    return finalTotal.divide(
   194	      new BigDecimal(installments),
   195	      2,
   196	      java.math.RoundingMode.HALF_EVEN
   197	    );
   198	  }
   199	
   200	  private BigDecimal calculateCredit(BigDecimal productsSubtotal, ClubTier clubTier) {
   201	    return RoundingUtil.roundHalfEven(
   202	      productsSubtotal.multiply(new BigDecimal(clubTier.getCreditPercentage()))
   203	    );
   204	  }
   205	
   206	  private boolean shouldGiveGift(BigDecimal productsSubtotal, ClubTier clubTier) {
   207	    return clubTier == ClubTier.GOLD &&
   208	           productsSubtotal.compareTo(new BigDecimal("500.00")) > 0;
   209	  }
   210	
   211	  public record SummaryItem(
   212	    String sku,
   213	    int quantity,
   214	    BigDecimal price
   215	  ) {}
   216	}
   217	package com.loja.order.util;
   218	
   219	import java.math.BigDecimal;
   220	import java.math.RoundingMode;
   221	
   222	public class RoundingUtil {
   223	  public static BigDecimal roundHalfEven(BigDecimal value) {
   224	    return value.setScale(2, RoundingMode.HALF_EVEN);
   225	  }
   226	
   227	  public static int ceilDays(double hours) {
   228	    return (int) Math.ceil(hours / 24.0);
   229	  }
   230	}
